contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _l1FeeOverhead) public payable {
        require(true);

        uint256 beforeOverhead = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), _l1FeeOverhead, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.l1FeeOverhead() == beforeOverhead);
    }

    receive() external payable {}
}

