pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint256 _l1FeeOverhead) internal {
        vm.assume(true);
        uint256 beforeOverhead;
        try c.l1FeeOverhead() returns (uint256 __r) { beforeOverhead = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), _l1FeeOverhead, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.l1FeeOverhead() == beforeOverhead);
    }

    function testFuzz_run(uint256 _l1FeeOverhead) public {
        _run(_l1FeeOverhead);
    }

    receive() external payable {}
}
